def rent_weight_to_low_income(apps, schema_editor):
    """The "low rent" criterion became "low income": organizations keep the weight they had given it."""
    Organization = apps.get_model("accounts", "Organization")
    for organization in Organization.objects.exclude(score_weights={}):
        weights = dict(organization.score_weights)
        if "low_rent" in weights:
            weights["low_income"] = weights.pop("low_rent")
            organization.score_weights = weights
            organization.save(update_fields=["score_weights"])


